    __asm__ ("sext.h %[lo], %[word]\n\t"
             "srai %[lo], %[lo], 4\n\t"
             "srai %[word], %[word], 20\n\t"
             "pack %[word], %[lo], %[word]"
             : [word] "+r" (v_x), [lo] "=&r" (low));
